function loadConfig() {
  try {
    if (!fs.existsSync(CONFIG_FILE)) return {};
    return JSON.parse(fs.readFileSync(CONFIG_FILE, "utf8"));
  } catch {
    return {};
  }
}

async function saveConfig(config) {
  await fsp.mkdir(CONFIG_DIR, { recursive: true, mode: 0o700 });
  await fsp.writeFile(CONFIG_FILE, `${JSON.stringify(config, null, 2)}\n`, { mode: 0o600 });
  await fsp.chmod(CONFIG_FILE, 0o600);
}

function buildBaseUrl(config = loadConfig()) {
  if (process.env.LOVART_API_BASE_URL) return process.env.LOVART_API_BASE_URL.replace(/\/$/, "");
  if (config.base_url) return String(config.base_url).replace(/\/$/, "");
  const protocol = process.env.LOVART_API_PROTOCOL || DEFAULT_PROTOCOL;
  const host = process.env.LOVART_API_HOST || DEFAULT_HOST;
  const port = process.env.LOVART_API_PORT || DEFAULT_PORT;
  return `${protocol}://${host}:${Number(port)}`;
}

function buildRuntime() {
  const config = loadConfig();
  return {
    baseUrl: buildBaseUrl(config),
    token: process.env.LOVART_API_TOKEN || config.token || DEFAULT_TOKEN,
    projectId: process.env.LOVART_PROJECT_ID || config.project_id || null,
    cliConfig: config.cli_config || null,
  };
}

function tokenSource(config = loadConfig()) {
  if (process.env.LOVART_API_TOKEN) return "env:LOVART_API_TOKEN";
  if (config.token) return "saved";
  return "none";
}

function maskToken(token) {
  if (!token) return "";
  if (token.length <= 8) return "****";
  return `${token.slice(0, 4)}...${token.slice(-4)}`;
}

function headers(token) {
  return { Authorization: `Bearer ${token}` };
}

async function requestJson(url, options = {}) {
  const response = await fetch(url, options);
  const text = await response.text();
  let payload = {};
  if (text) {
    try {
      payload = JSON.parse(text);
    } catch (error) {
      throw new Error(`Invalid JSON response from ${url}: ${error.message}`);
    }
  }
  if (!response.ok) {
    const detail = payload?.message || payload?.error || text || response.statusText;
    throw new Error(`HTTP ${response.status} ${response.statusText}: ${detail}`);
  }
  return payload;
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function listJobs(rt, limit) {
  const url = new URL(`${rt.baseUrl}/v1/jobs`);
  if (limit) url.searchParams.set("limit", String(limit));
  return requestJson(url, { headers: headers(rt.token) });
}

async function getJob(rt, id) {
  return requestJson(`${rt.baseUrl}/v1/jobs/${encodeURIComponent(id)}`, { headers: headers(rt.token) });
}

async function getCliConfig(rt) {
  if (rt.cliConfig) return rt.cliConfig;
  const cacheKey = `${rt.baseUrl}|${rt.token}`;
  if (!cliConfigCache.has(cacheKey)) {
    cliConfigCache.set(cacheKey, requestJson(`${rt.baseUrl}/v1/cli/config`, { headers: headers(rt.token) }).then(async payload => {
      const current = loadConfig();
      await saveConfig({ ...current, cli_config: payload, updated_at: new Date().toISOString() });
      rt.cliConfig = payload;
      return payload;
    }));
  }
  return cliConfigCache.get(cacheKey);
}

async function waitForJob(rt, id, pollSeconds) {
  const deadline = Date.now() + Math.max(pollSeconds, 0) * 1000;
  let last = await getJob(rt, id);
  while (pollSeconds > 0 && Date.now() < deadline) {
    const status = last.status || last.job?.status;
    if (isTerminalStatus(status)) return last;
    await sleep(1000);
    last = await getJob(rt, id);
  }
  return last;
}

function must(value, name) {
  if (value === undefined || value === null || value === "") throw new Error(`Missing required option: --${name}`);
  return value;
}

function validateChoice(name, value, allowed) {
  if (!allowed.includes(value)) throw new Error(`Invalid ${name}: ${value}. Allowed: ${allowed.join(", ")}`);
}

function validateImageDimensions(model, width, height, size, resolution) {
  if (width == null && height == null) return;
  if (width == null || height == null) throw new Error("width and height must be provided together");
  if (model !== "GPT Image 2") throw new Error("width and height are only supported for GPT Image 2");
  if (size != null || resolution != null) throw new Error("width and height cannot be combined with size or resolution");
  if (width <= 0 || height <= 0) throw new Error("width and height must be positive integers");
  if (width % 16 !== 0 || height % 16 !== 0) throw new Error("width and height must both be multiples of 16");
  if (width * height < MIN_GPT_IMAGE_2_PIXELS) throw new Error(`width * height must be at least ${MIN_GPT_IMAGE_2_PIXELS} for GPT Image 2`);
  if (width * height > MAX_IMAGE_PIXELS) throw new Error(`width * height must not exceed ${MAX_IMAGE_PIXELS}`);
}

function validateImageSizeForModel(model, size) {
  if (model === "GPT Image 2" && !GPT_IMAGE_2_STABLE_SIZES.includes(size)) {
    throw new Error(`GPT Image 2 supports ratios: ${GPT_IMAGE_2_STABLE_SIZES.join(", ")}`);
  }
}

function validateVideo(model, ratio, quality, duration, referenceMode) {
  validateChoice("model", model, VIDEO_MODELS);
  if (!VIDEO_MODEL_RATIOS[model].includes(ratio)) throw new Error(`${model} supports ratios: ${VIDEO_MODEL_RATIOS[model].join(", ")}`);
  validateChoice("quality", quality, VIDEO_RESOLUTIONS);
  const [low, high] = VIDEO_MODEL_DURATION_RANGE[model];
  if (duration < low || duration > high) throw new Error(`${model} supports duration ${low}-${high}`);
  if (referenceMode != null) {
    validateChoice("reference_mode", referenceMode, VIDEO_REFERENCE_MODES);
    if (model === "Kling 3.0" && referenceMode !== "startEnd") throw new Error('Kling 3.0 only supports reference_mode "startEnd"');
  }
}

function mimeType(filename) {
  const ext = path.extname(filename).toLowerCase();
  return {
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".png": "image/png",
    ".gif": "image/gif",
    ".webp": "image/webp",
    ".bmp": "image/bmp",
    ".tiff": "image/tiff",
    ".mp4": "video/mp4",
    ".mov": "video/quicktime",
    ".avi": "video/x-msvideo",
    ".mkv": "video/x-matroska",
    ".mp3": "audio/mpeg",
    ".wav": "audio/wav",
    ".m4a": "audio/mp4",
  }[ext] || "application/octet-stream";
}

function sha1Hex(value) {
  return crypto.createHash("sha1").update(value, "utf8").digest("hex");
}

function hmacSha1Hex(key, value) {
  return crypto.createHmac("sha1", key).update(value, "utf8").digest("hex");
}

function hmacSha256Hex(key, value) {
  return crypto.createHmac("sha256", key).update(value, "utf8").digest("hex");
}

function buildLovartOpenapiHeaders(method, signedPath, accessKey, secretKey) {
  const ts = String(Math.floor(Date.now() / 1000));
  const sig = hmacSha256Hex(secretKey, `${method}\n${signedPath}\n${ts}`);
  return {
    "X-Access-Key": accessKey,
    "X-Timestamp": ts,
    "X-Signature": sig,
    "X-Signed-Method": method,
    "X-Signed-Path": signedPath,
    "User-Agent": "LovartNodeCLI/1.0",
  };
}

function quoteHeader(value) {
  return encodeURIComponent(String(value)).replace(/[!'()*]/g, ch => `%${ch.charCodeAt(0).toString(16).toUpperCase()}`);
}

function buildCosAuthorization(method, pathname, signedHeaders, cfg) {
  const now = Math.floor(Date.now() / 1000);
  const expire = now + 3600;
  const keyTime = `${now};${expire}`;
  const signKey = hmacSha1Hex(cfg.COS_SECRET_KEY, keyTime);
  const normalized = {};
  for (const [key, value] of Object.entries(signedHeaders)) normalized[key.toLowerCase()] = quoteHeader(value);
  const signedKeys = Object.keys(normalized).sort();
  const headerList = signedKeys.join(";");
  const canonicalHeaders = signedKeys.map(key => `${key}=${normalized[key]}`).join("&");
  const httpString = `${method.toLowerCase()}\n${pathname}\n\n${canonicalHeaders}\n`;
  const stringToSign = `sha1\n${keyTime}\n${sha1Hex(httpString)}\n`;
  const signature = hmacSha1Hex(signKey, stringToSign);
  return [
    "q-sign-algorithm=sha1",
    `q-ak=${cfg.COS_SECRET_ID}`,
    `q-sign-time=${keyTime}`,
    `q-key-time=${keyTime}`,
    `q-header-list=${headerList}`,
    "q-url-param-list=",
    `q-signature=${signature}`,
  ].join("&");
}

async function fileBlob(localPath) {
  const buffer = await fsp.readFile(localPath);
  return new Blob([buffer], { type: mimeType(localPath) });
}

async function uploadLocalFile(localPath, rt) {
  const full = path.resolve(localPath);
  if (!fs.existsSync(full)) throw new Error(`File not found: ${localPath}`);
  const remoteConfig = await getCliConfig(rt);
  const upload = remoteConfig.upload || {};
  const cfg = {
    LOVART_UPLOAD_BASE_URL: upload.base_url || upload.baseUrl || DEFAULT_LOVART_UPLOAD_BASE_URL,
    LOVART_UPLOAD_PATH: upload.path || upload.upload_path || upload.uploadPath || DEFAULT_LOVART_UPLOAD_PATH,
    LOVART_ACCESS_KEY: upload.access_key || upload.accessKey || "",
    LOVART_SECRET_KEY: upload.secret_key || upload.secretKey || "",
  };
  const missing = Object.entries(cfg).filter(([, value]) => !value).map(([key]) => key);
  if (missing.length) throw new Error(`Server CLI upload config is missing: ${missing.join(", ")}`);
  const form = new FormData();
  form.append("file", await fileBlob(full), path.basename(full));
  const payload = await requestJson(`${cfg.LOVART_UPLOAD_BASE_URL.replace(/\/$/, "")}${cfg.LOVART_UPLOAD_PATH}`, {
    method: "POST",
    headers: buildLovartOpenapiHeaders("POST", cfg.LOVART_UPLOAD_PATH, cfg.LOVART_ACCESS_KEY, cfg.LOVART_SECRET_KEY),
    body: form,
  });
  if (payload.code !== 0) throw new Error(`Lovart upload failed: ${payload.message || "unknown error"}`);
  const url = String(payload?.data?.url || "").trim();
  if (!url) throw new Error("Lovart upload did not return a url.");
  return url;
}

async function uploadLocalFileToAssetCos(localPath, rt, objectKey) {
  const full = path.resolve(localPath);
  if (!fs.existsSync(full)) throw new Error(`File not found: ${localPath}`);
  const remoteConfig = await getCliConfig(rt);
  const cos = remoteConfig.cos || {};
  const cfg = {
    COS_SECRET_ID: cos.secret_id || cos.secretId || "",
    COS_SECRET_KEY: cos.secret_key || cos.secretKey || "",
    COS_BUCKET: cos.bucket || "",
    COS_REGION: cos.region || "",
    COS_BASE_URL: cos.base_url || cos.baseUrl || "",
    COS_PATH_PREFIX: cos.path_prefix || cos.pathPrefix || DEFAULT_COS_PATH_PREFIX,
  };
  const missing = ["COS_SECRET_ID", "COS_SECRET_KEY", "COS_BUCKET", "COS_REGION"].filter(key => !cfg[key]);
  if (missing.length) throw new Error(`Server CLI asset COS config is missing: ${missing.join(", ")}`);
  const objectName = objectKey || `${cfg.COS_PATH_PREFIX.replace(/^\/|\/$/g, "")}/${Date.now()}-${path.basename(full)}`;
  const pathname = `/${objectName.replace(/^\//, "")}`;
  const host = `${cfg.COS_BUCKET}.cos.${cfg.COS_REGION}.myqcloud.com`;
  const payload = await fsp.readFile(full);
  const contentType = mimeType(full);
  const signedHeaders = { Host: host, "Content-Type": contentType, "Content-Length": String(payload.length) };
  const authorization = buildCosAuthorization("PUT", pathname, signedHeaders, cfg);
  const response = await fetch(`https://${host}${pathname}`, {
    method: "PUT",
    headers: { ...signedHeaders, Authorization: authorization },
    body: payload,
  });
  if (response.status !== 200) throw new Error(`Asset COS upload failed [${response.status}]: ${await response.text()}`);
  const baseUrl = (cfg.COS_BASE_URL || `https://${host}`).replace(/\/$/, "");
  return `${baseUrl}${pathname}`;
}

async function ensurePublicUrl(value, rt) {
  if (value == null) return null;
  if (/^(https?:\/\/|asset:\/\/|local-asset:\/\/|lasset_)/.test(value)) return value;
  const full = path.resolve(value);
  if (fs.existsSync(full)) return uploadLocalFile(full, rt);
  throw new Error(`Reference file not found and not a URL: ${value}`);
}

async function ensureAssetSourceUrl(value, rt) {
  if (/^https?:\/\//.test(value)) return value;
  if (value.startsWith("asset://")) throw new Error("asset_upload requires a source URL or local file path, not an existing asset:// value");
  const full = path.resolve(value);
  if (fs.existsSync(full)) return uploadLocalFileToAssetCos(full, rt);
  throw new Error(`Asset source not found and not a URL: ${value}`);
}

async function buildImageRequest(options) {
  const model = options.model || DEFAULT_IMAGE_MODEL;
  const quality = options.quality || DEFAULT_IMAGE_QUALITY;
  const width = intOrNull(options.width);
  const height = intOrNull(options.height);
  const widthMode = width != null || height != null;
  const size = widthMode ? null : (options.ratio || "16:9");
  const resolution = widthMode ? null : (options.resolution || "1K");
  validateChoice("model", model, IMAGE_MODELS);
  validateChoice("quality", quality, IMAGE_QUALITIES);
  validateImageDimensions(model, width, height, size, resolution);
  if (!widthMode) {
    validateChoice("size", size, IMAGE_SIZES);
    validateImageSizeForModel(model, size);
    validateChoice("resolution", resolution, IMAGE_RESOLUTIONS);
  }
  const body = { async: true, type: "image", prompt: must(options.prompt, "prompt"), model, quality };
  if (widthMode) {
    body.width = width;
    body.height = height;
  } else {
    body.size = size;
    body.resolution = resolution;
  }
  if (options.references?.length) body.reference_image_urls = await Promise.all(options.references.map(value => ensurePublicUrl(value, options.runtime)));
  if (options.projectId) body.project_id = options.projectId;
  return body;
}

async function buildVideoRequest(options) {
  const model = options.model || DEFAULT_VIDEO_MODEL;
  const ratio = options.ratio || "16:9";
  const quality = options.quality || "720p";
  const duration = Number(options.duration ?? 5);
  validateVideo(model, ratio, quality, duration, options.referenceMode);
  const body = { async: true, type: "video", prompt: must(options.prompt, "prompt"), model, ratio, quality, duration };
  if (options.referenceMode) body.reference_mode = options.referenceMode;
  if (options.referenceImages?.length) body.reference_image_urls = await Promise.all(options.referenceImages.map(value => ensurePublicUrl(value, options.runtime)));
  if (options.referenceVideos?.length) body.reference_video_urls = await Promise.all(options.referenceVideos.map(value => ensurePublicUrl(value, options.runtime)));
  if (options.referenceAudios?.length) body.reference_audio_urls = await Promise.all(options.referenceAudios.map(value => ensurePublicUrl(value, options.runtime)));
  if (options.projectId) body.project_id = options.projectId;
  return body;
}

async function buildAssetUploadRequest(options) {
  const assetType = must(options.assetType, "asset-type");
  validateChoice("asset_type", assetType, ASSET_TYPES);
  const body = {
    async: true,
    asset_type: assetType,
    source_url: await ensureAssetSourceUrl(must(options.source, "source"), options.runtime),
  };
  if (options.contentType) body.content_type = options.contentType;
  if (options.displayName) body.display_name = options.displayName;
  return body;
}

async function buildRemoveBackgroundRequest(images, autoCropSubject, rt) {
  if (!images?.length) throw new Error("images is required");
  const normalized = await Promise.all(images.filter(Boolean).map(value => ensurePublicUrl(value, rt)));
  if (!normalized.length) throw new Error("images must contain at least one URL or local file path");
  const body = { images: normalized, mode: 1 };
  if (autoCropSubject) body.auto_crop_subject = true;
  return body;
}

async function submitGeneration(rt, body) {
  return requestJson(`${rt.baseUrl}/v1/generate`, {
    method: "POST",
    headers: { ...headers(rt.token), "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

async function submitAssetUpload(rt, body) {
  return requestJson(`${rt.baseUrl}/v1/kit/assets/upload`, {
    method: "POST",
    headers: { ...headers(rt.token), "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

async function getManagedAsset(rt, assetId) {
  return requestJson(`${rt.baseUrl}/v1/assets/${encodeURIComponent(assetId)}`, {
    headers: headers(rt.token),
  });
}

async function listManagedAssets(rt, limit) {
  const url = new URL(`${rt.baseUrl}/v1/assets`);
  if (limit) url.searchParams.set("limit", String(limit));
  return requestJson(url, { headers: headers(rt.token) });
}

async function submitRemoveBackground(rt, body) {
  return requestJson(`${rt.baseUrl}/v2/tools/remove-background`, {
    method: "POST",
    headers: { ...headers(rt.token), "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

async function uploadBinaryToRunningHub(filename, content, apiKey, contentType) {
  const form = new FormData();
  form.append("file", new Blob([content], { type: contentType || mimeType(filename) }), filename);
  const payload = await requestJson("https://www.runninghub.cn/openapi/v2/media/upload/binary", {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}` },
    body: form,
  });
  if (Number(payload.code ?? -1) !== 0) throw new Error(`RunningHub upload failed: ${payload.message || "unknown error"}`);
  return String(payload?.data?.download_url || "");
}

async function ensureRunninghubImageUrl(value, apiKey) {
  if (/^https?:\/\//.test(value)) {
    const response = await fetch(value);
    if (!response.ok) throw new Error(`HTTP ${response.status}: failed to fetch image for RunningHub`);
    const name = path.basename(new URL(value).pathname) || "image.png";
    return uploadBinaryToRunningHub(name, await response.arrayBuffer(), apiKey, response.headers.get("content-type") || undefined);
  }
  if (value.startsWith("data:")) {
    const [header, payload] = value.split(",", 2);
    const mime = header.includes(";") && header.includes(":") ? header.split(":", 2)[1].split(";", 1)[0] : "image/png";
    return uploadBinaryToRunningHub("image", Buffer.from(payload, "base64"), apiKey, mime);
  }
  const full = path.resolve(value);
  if (!fs.existsSync(full)) throw new Error(`RunningHub upload source not found: ${value}`);
  return uploadBinaryToRunningHub(path.basename(full), await fsp.readFile(full), apiKey, mimeType(full));
}

async function submitRunninghubWorkflowRaw(apiKey, workflowId, body) {
  return requestJson(`https://www.runninghub.cn/openapi/v2/run/workflow/${encodeURIComponent(workflowId)}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
    body: JSON.stringify(body),
  });
}

async function maybePoll(rt, submitResult, pollSeconds) {
  const submitId = submitResult.job_id || submitResult.submit_id || submitResult.id;
  if (!submitId || Number(pollSeconds || 0) <= 0) return submitResult;
  return { submit: submitResult, result: await waitForJob(rt, submitId, Number(pollSeconds)) };
}

function normalizeStatus(value) {
  if (!value) return "unknown";
  const mapping = {
    queued: "queued",
    pending: "queued",
    running: "running",
    processing: "running",
    submitted: "running",
    completed: "succeeded",
    success: "succeeded",
    succeeded: "succeeded",
    done: "succeeded",
    failed: "failed",
    error: "failed",
    cancelled: "cancelled",
    canceled: "cancelled",
    interrupted: "interrupted",
    timeout: "failed",
  };
  const lowered = String(value).trim().toLowerCase();
  return mapping[lowered] || lowered;
}

function isTerminalStatus(value) {
  return ["succeeded", "failed", "cancelled", "interrupted"].includes(normalizeStatus(value));
}

function explainGenerationError(job) {
  const raw = String(job?.error || "").trim();
  if (raw !== "Error: success") return raw || null;
  const payload = job?.payload || {};
  const hasImageReference = Array.isArray(payload.reference_image_urls) && payload.reference_image_urls.length > 0;
  if (!hasImageReference) return raw;
  return "Lovart rejected the reference image but returned no actionable reason (raw upstream error: Error: success). For a real-person reference, upload it with asset_upload, wait until moderation_status is active, then use the returned asset_url.";
}

function artifactListFromJob(job) {
  const result = job.result || {};
  const pollData = result.poll_response?.data || {};
  const artifacts = pollData.artifacts || [];
  const normalized = artifacts.map(artifact => ({
    type: artifact.type,
    url: artifact.content,
    format: artifact.metadata?.format,
    width: artifact.metadata?.width,
    height: artifact.metadata?.height,
  }));
  if (result.artifact_url && normalized.length === 0) normalized.push({ type: result.type, url: result.artifact_url });
  return normalized;
}

function isAssetUploadJob(job) {
  const payload = job.payload || {};
  const result = job.result || {};
  return payload.command === "asset-upload" || result.command === "asset-upload" || result.via === "kit-asset-upload";
}

function buildQueryResultCommand(submitId) {
  return submitId ? `lovart --json query_result --submit-id ${submitId}` : null;
}

function truncateText(value, limit = PROMPT_PREVIEW_MAX) {
  if (value == null) return null;
  const text = String(value);
  return text.length <= limit ? text : `${text.slice(0, limit - 3)}...`;
}

function summarizeJob(job) {
  const payload = job.payload || {};
  const result = job.result || {};
  const phaseTimings = result.phase_timings || {};
  const status = normalizeStatus(job.status);
  const done = isTerminalStatus(status);
  const submitId = job.id;
  const nextAction = done ? "none" : "poll";
  if (isAssetUploadJob(job)) {
    const asset = result.asset || {};
    const assetFile = asset.file || {};
    const uploadFile = result.file || {};
    const assetUri = asset.asset_uri;
    return {
      submit_id: submitId,
      status,
      done,
      terminal: done,
      next_action: nextAction,
      recommended_command: done ? null : buildQueryResultCommand(submitId),
      message: done && assetUri ? "Asset upload completed. Use asset_url only after moderation_status is active." : done ? "Asset upload completed." : "Asset upload still running. Use query_result again with the same submit_id.",
      kind: "asset-upload",
      command: "asset_upload",
      asset_type: result.asset_type || payload.asset_type || payload.assetType,
      source_url: uploadFile.source_url || payload.source_url || payload.sourceUrl || payload.file_url || payload.fileUrl,
      display_name: uploadFile.display_name || payload.display_name || payload.displayName,
      content_type: uploadFile.content_type || payload.content_type || payload.contentType,
      created_at: job.created_at,
      updated_at: job.updated_at,
      asset_id: asset.id,
      asset_uri: assetUri,
      asset_url: assetFile.url,
      asset_file_name: assetFile.fileName || assetFile.file_name,
      asset_width: assetFile.width,
      asset_height: assetFile.height,
      asset_duration: assetFile.duration,
      moderation_status: asset.moderation_status,
      timings: { submit_ms: phaseTimings.submit_ms, poll_wall_ms: phaseTimings.poll_wall_ms, total_ms: phaseTimings.total_ms },
      error: job.error,
    };
  }
  return {
    submit_id: submitId,
    status,
    done,
    terminal: done,
    next_action: nextAction,
    recommended_command: done ? null : buildQueryResultCommand(submitId),
    message: done ? "Task completed. No further polling needed." : "Task still running. Use query_result again with the same submit_id.",
    kind: "generation",
    type: payload.type || result.type,
    model: payload.model,
    prompt: payload.prompt,
    prompt_preview: truncateText(payload.prompt),
    ratio: payload.size || payload.ratio,
    resolution: payload.resolution || payload.quality,
    quality: payload.quality,
    duration: payload.duration,
    reference_mode: payload.reference_mode,
    created_at: job.created_at,
    updated_at: job.updated_at,
    task_id: result.task_id,
    artifact_url: result.artifact_url,
    artifacts: artifactListFromJob(job),
    timings: { submit_ms: phaseTimings.submit_ms, poll_wall_ms: phaseTimings.poll_wall_ms, total_ms: phaseTimings.total_ms },
    error: explainGenerationError(job),
    raw_error: job.error || null,
  };
}

function summarizeJobList(result, limit) {
  const jobs = result.jobs || [];
  const visible = jobs.filter(job => !isAssetUploadJob(job));
  return {
    ok: result.ok ?? true,
    count: visible.length,
    total: result.total ?? visible.length,
    limit,
    hidden_asset_upload_jobs: jobs.length - visible.length,
    items: visible.map(summarizeJob),
  };
}

function summarizeSubmitResult(result) {
  if (result.submit && result.result) {
    const submit = result.submit || {};
    const polled = result.result || {};
    const job = polled.job || polled.item || polled;
    const summary = summarizeJob(job);
    if (rawOutput) summary.submit_ack = submit;
    return {
      ok: true,
      submit_id: summary.submit_id || submit.job_id || submit.submit_id,
      polled: true,
      done: summary.done,
      terminal: summary.terminal,
      next_action: summary.next_action,
      recommended_command: summary.recommended_command,
      message: summary.message,
      result: summary,
    };
  }
  const submitId = result.job_id || result.submit_id || result.id;
  return {
    ok: true,
    submit_id: submitId,
    polled: false,
    status: normalizeStatus(result.status || result.job?.status),
    done: false,
    terminal: false,
    next_action: "poll",
    recommended_command: buildQueryResultCommand(submitId),
    message: "Task submitted. Use query_result with the submit_id to check progress.",
  };
}

function summarizeAssetUploadResult(result) {
  const raw = typeof result.result === "object" && result.result ? result.result : result;
  const asset = raw.asset || {};
  const fileInfo = raw.file || {};
  const assetFile = asset.file || {};
  const timings = raw.phase_timings || {};
  return {
    ok: Boolean(result.ok ?? true),
    kind: "asset-upload",
    asset_type: raw.asset_type,
    source_url: fileInfo.source_url,
    display_name: fileInfo.display_name,
    content_type: fileInfo.content_type,
    asset_id: asset.id,
    asset_uri: asset.asset_uri,
    moderation_status: asset.moderation_status,
    asset_url: assetFile.url,
    asset_file_name: assetFile.fileName || assetFile.file_name,
    replicas: raw.replicas,
    timings: { total_ms: timings.total_ms },
  };
}

function humanizeForText(data) {
  if (Array.isArray(data)) return data.map(humanizeForText);
  if (data && typeof data === "object") {
    const cloned = {};
    for (const [key, value] of Object.entries(data)) {
      if (key === "prompt_preview") continue;
      if (key === "prompt" && typeof data.prompt_preview === "string") cloned[key] = data.prompt_preview;
      else cloned[key] = humanizeForText(value);
    }
    return cloned;
  }
  return data;
}

function writeData(data, message = "") {
  if (jsonOutput) {
    console.log(JSON.stringify(data, null, 2));
    return;
  }
  const human = humanizeForText(data);
  if (message) console.log(message);
  printValue(human);
}

function printValue(value, indent = 0) {
  const prefix = "  ".repeat(indent);
  if (Array.isArray(value)) {
    value.forEach((item, index) => {
      if (item && typeof item === "object") {
        console.log(`${prefix}[${index}]`);
        printValue(item, indent + 1);
      } else {
        console.log(`${prefix}- ${item}`);
      }
    });
    return;
  }
  if (value && typeof value === "object") {
    for (const [key, item] of Object.entries(value)) {
      if (item && typeof item === "object") {
        console.log(`${prefix}${key}:`);
        printValue(item, indent + 1);
      } else if (item !== undefined) {
        console.log(`${prefix}${key}: ${item}`);
      }
    }
    return;
  }
  if (value !== "" && value != null) console.log(String(value));
}

