function commandHelp(name) {
  return `Usage: lovart ${name} [options]\n\n${HELP[name] || COMMANDS[name] || ""}`;
}

function parseArgs(argv) {
  const globals = { json: false, raw: false };
  const rest = [];
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--json") globals.json = true;
    else if (arg === "--raw") globals.raw = true;
    else rest.push(arg);
  }
  const command = rest[0];
  const commandArgs = rest.slice(1);
  return { globals, command, options: normalizeOptions(parseOptions(commandArgs)), rawArgs: commandArgs };
}

function normalizeOptions(options) {
  if (options.modelVersion !== undefined && options.model === undefined) options.model = options.modelVersion;
  return options;
}

function parseOptions(args) {
  const options = { _: [] };
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === "--") {
      options._.push(...args.slice(i + 1));
      break;
    }
    if (arg.startsWith("--")) {
      const eq = arg.indexOf("=");
      const rawKey = eq === -1 ? arg.slice(2) : arg.slice(2, eq);
      const key = camel(rawKey);
      let value;
      if (eq !== -1) value = arg.slice(eq + 1);
      else if (args[i + 1] && !args[i + 1].startsWith("--")) value = args[++i];
      else value = true;
      addOption(options, key, value);
    } else if (arg === "-h") {
      options.help = true;
    } else {
      options._.push(arg);
    }
  }
  return options;
}

function addOption(options, key, value) {
  if (options[key] === undefined) options[key] = value;
  else if (Array.isArray(options[key])) options[key].push(value);
  else options[key] = [options[key], value];
}

function camel(key) {
  return key.replace(/-([a-z])/g, (_, char) => char.toUpperCase());
}

function arr(value) {
  if (value === undefined) return [];
  return Array.isArray(value) ? value : [value];
}

function intOrNull(value) {
  if (value === undefined || value === null || value === "") return null;
  const parsed = Number(value);
  if (!Number.isInteger(parsed)) throw new Error(`Expected integer, got: ${value}`);
  return parsed;
}

async function promptLine(label) {
  const rl = readline.createInterface({ input, output: outputStream });
  try {
    return (await rl.question(label)).trim();
  } finally {
    rl.close();
  }
}

async function runAuth(options) {
  const subcommand = options._[0] || "status";
  const config = loadConfig();
  if (subcommand === "login") {
    const token = String(options.token || options._[1] || await promptLine("Lovart auth token: ")).trim();
    if (!token) throw new Error("Auth token is required.");
    const next = { ...config, token, updated_at: new Date().toISOString() };
    if (options.baseUrl) next.base_url = String(options.baseUrl).replace(/\/$/, "");
    if (options.projectId) next.project_id = String(options.projectId);
    let cliConfigCached = false;
    let cliConfigError = null;
    try {
      next.cli_config = await requestJson(`${buildBaseUrl(next)}/v1/cli/config`, { headers: headers(token) });
      cliConfigCached = true;
    } catch (error) {
      delete next.cli_config;
      cliConfigError = String(error?.message || error);
    }
    await saveConfig(next);
    const response = {
      ok: true,
      config_file: CONFIG_FILE,
      token_source: tokenSource(next),
      token: maskToken(token),
      base_url: buildBaseUrl(next),
      project_id: next.project_id || null,
      cli_config_cached: cliConfigCached,
    };
    if (cliConfigError) response.cli_config_error = cliConfigError;
    return writeData(response, "Lovart auth token saved");
  }
  if (subcommand === "logout") {
    const next = { ...config };
    delete next.token;
    delete next.cli_config;
    next.updated_at = new Date().toISOString();
    await saveConfig(next);
    return writeData({
      ok: true,
      config_file: CONFIG_FILE,
      token_source: tokenSource(next),
      base_url: buildBaseUrl(next),
      project_id: next.project_id || null,
    }, "Lovart auth token removed");
  }
  if (subcommand === "status") {
    const rt = buildRuntime();
    return writeData({
      ok: true,
      config_file: CONFIG_FILE,
      token_configured: Boolean(rt.token),
      token_source: tokenSource(config),
      token: maskToken(rt.token),
      base_url: rt.baseUrl,
      project_id: rt.projectId,
    }, "Lovart auth status");
  }
  throw new Error(`Unknown auth subcommand: ${subcommand}`);
}

function normalizeAiTargets(value) {
  const raw = String(value || "codex").trim().toLowerCase();
  if (raw === "all" || raw === "*") return Object.keys(SKILL_TARGETS);
  const aliases = {
    claudeCode: "claude",
    "claude-code": "claude",
    agent: "antigravity",
    agents: "antigravity",
  };
  const target = aliases[raw] || raw;
  if (!SKILL_TARGETS[target]) {
    throw new Error(`Unsupported AI target: ${value}. Supported: ${Object.keys(SKILL_TARGETS).join(", ")}, all`);
  }
  return [target];
}

async function installSkillForTarget(ai, options) {
  const baseDir = options.global ? homedir() : process.cwd();
  const targetDir = path.join(baseDir, ...SKILL_TARGETS[ai]);
  const exists = fs.existsSync(path.join(targetDir, "SKILL.md"));
  if (exists && options.skipExisting) {
    return { ai, target_dir: targetDir, installed: false, skipped: true, reason: "exists" };
  }
  if (exists) await fsp.rm(targetDir, { recursive: true, force: true });
  await fsp.mkdir(path.dirname(targetDir), { recursive: true });
  await fsp.cp(SKILL_ASSET_DIR, targetDir, { recursive: true });
  return { ai, target_dir: targetDir, installed: true, skipped: false, updated: exists };
}

async function runSkill(options) {
  const subcommand = options._[0] || "init";
  if (subcommand !== "init") throw new Error(`Unknown skill subcommand: ${subcommand}`);
  const targets = normalizeAiTargets(options.ai);
  const results = [];
  for (const target of targets) {
    results.push(await installSkillForTarget(target, options));
  }
  return writeData({
    ok: true,
    source: "npm:lovart",
    global: Boolean(options.global),
    force: Boolean(options.force),
    skip_existing: Boolean(options.skipExisting),
    results,
  }, "Lovart skill installed");
}

async function runCommand(command, options) {
  const rt = buildRuntime();
  switch (command) {
    case "auth":
      return runAuth(options);
    case "skill":
      return runSkill(options);
    case "text2image": {
      const body = await buildImageRequest({ ...options, runtime: rt, resolution: options.resolutionType, projectId: rt.projectId });
      const result = await maybePoll(rt, await submitGeneration(rt, body), options.poll);
      return writeData(rawOutput ? result : summarizeSubmitResult(result), "Text-to-image submitted");
    }
    case "image2image": {
      const body = await buildImageRequest({ ...options, runtime: rt, resolution: options.resolutionType, references: arr(options.reference), ratio: options.ratio || "1:1", projectId: rt.projectId });
      const result = await maybePoll(rt, await submitGeneration(rt, body), options.poll);
      return writeData(rawOutput ? result : summarizeSubmitResult(result), "Image-to-image submitted");
    }
    case "text2video": {
      const body = await buildVideoRequest({ ...options, runtime: rt, projectId: rt.projectId });
      const result = await maybePoll(rt, await submitGeneration(rt, body), options.poll);
      return writeData(rawOutput ? result : summarizeSubmitResult(result), "Text-to-video submitted");
    }
    case "frames2video": {
      const body = await buildVideoRequest({ ...options, runtime: rt, referenceMode: "startEnd", referenceImages: [must(options.firstFrame, "first-frame"), must(options.lastFrame, "last-frame")], projectId: rt.projectId });
      const result = await maybePoll(rt, await submitGeneration(rt, body), options.poll);
      return writeData(rawOutput ? result : summarizeSubmitResult(result), "Frames-to-video submitted");
    }
    case "multiref2video": {
      const model = options.model || "Seedance 2.0";
      if (!["Seedance 2.0", "Seedance 2.0 Fast", "Seedance 2.0 Mini"].includes(model)) throw new Error("This command only supports: Seedance 2.0, Seedance 2.0 Fast, Seedance 2.0 Mini");
      const referenceImages = arr(options.referenceImage);
      const referenceVideos = arr(options.referenceVideo);
      const referenceAudios = arr(options.referenceAudio);
      if (!referenceImages.length && !referenceVideos.length && !referenceAudios.length) throw new Error("Provide at least one reference asset.");
      const body = await buildVideoRequest({ ...options, runtime: rt, model, referenceMode: "multiImage", referenceImages, referenceVideos, referenceAudios, projectId: rt.projectId });
      const result = await maybePoll(rt, await submitGeneration(rt, body), options.poll);
      return writeData(rawOutput ? result : summarizeSubmitResult(result), "Multi-reference video submitted");
    }
    case "videoedit": {
      const model = options.model || "Seedance 2.0";
      if (!["Seedance 2.0", "Seedance 2.0 Fast", "Seedance 2.0 Mini"].includes(model)) throw new Error("This command only supports: Seedance 2.0, Seedance 2.0 Fast, Seedance 2.0 Mini");
      const referenceImages = arr(options.referenceImage);
      const referenceVideos = arr(options.referenceVideo);
      const referenceAudios = arr(options.referenceAudio);
      if (!referenceVideos.length && !referenceImages.length) throw new Error("Provide at least one reference video or reference image.");
      const body = await buildVideoRequest({ ...options, runtime: rt, model, referenceMode: "videoEdit", referenceImages, referenceVideos, referenceAudios, projectId: rt.projectId });
      const result = await maybePoll(rt, await submitGeneration(rt, body), options.poll);
      return writeData(rawOutput ? result : summarizeSubmitResult(result), "Video-edit submitted");
    }
    case "asset_upload": {
      const body = await buildAssetUploadRequest({ ...options, runtime: rt });
      const result = await submitAssetUpload(rt, body);
      return writeData(rawOutput ? result : summarizeAssetUploadResult(result), "Asset upload submitted");
    }
    case "asset_list": {
      const result = await listManagedAssets(rt, options.limit ? Number(options.limit) : undefined);
      return writeData(rawOutput ? result : {
        ok: result.ok ?? true,
        count: result.count ?? result.assets?.length ?? 0,
        items: result.assets || result.items || [],
      }, "Managed asset list");
    }
    case "asset_status": {
      const result = await getManagedAsset(rt, must(options.assetId, "asset-id"));
      return writeData(rawOutput ? result : { ok: true, ...result.asset }, "Managed asset status");
    }
    case "remove_background": {
      const provider = options.provider || "lovart";
      validateChoice("provider", provider, ["lovart", "runninghub"]);
      if (provider === "lovart") {
        const body = await buildRemoveBackgroundRequest(arr(options.image), Boolean(options.autoCropSubject), rt);
        const result = await submitRemoveBackground(rt, body);
        return writeData(rawOutput ? result : { ok: true, provider: "lovart", result }, "Remove background completed");
      }
      const key = options.apiKey || process.env.RUNNINGHUB_API_KEY;
      if (!key) throw new Error("Provide --api-key or set RUNNINGHUB_API_KEY for --provider runninghub");
      const workflowId = options.autoCropSubject ? "2054898873558151170" : "2014701119468998657";
      const imageNodeId = options.autoCropSubject ? "12" : "4";
      const image = must(arr(options.image)[0], "image");
      const imageUrl = await ensureRunninghubImageUrl(image, key);
      const body = { addMetadata: false, nodeInfoList: [{ nodeId: imageNodeId, fieldName: "image", fieldValue: imageUrl }], instanceType: "default", usePersonalQueue: false };
      const result = await submitRunninghubWorkflowRaw(key, workflowId, body);
      return writeData(rawOutput ? result : { ok: true, provider: "runninghub", result }, "Remove background submitted");
    }
    case "runninghub_run": {
      const key = options.apiKey || process.env.RUNNINGHUB_API_KEY;
      if (!key) throw new Error("Provide --api-key or set RUNNINGHUB_API_KEY");
      const body = JSON.parse(must(options.bodyJson, "body-json"));
      const result = await submitRunninghubWorkflowRaw(key, must(options.workflowId, "workflow-id"), body);
      return writeData(rawOutput ? result : { ok: true, provider: "runninghub", result }, "RunningHub submitted");
    }
    case "list_task": {
      const limit = options.limit ? Number(options.limit) : undefined;
      const result = await listJobs(rt, limit);
      return writeData(rawOutput ? result : summarizeJobList(result, limit), "Task list");
    }
    case "query_result": {
      const submitId = must(options.submitId, "submit-id");
      const result = await getJob(rt, submitId);
      return writeData(rawOutput ? result : { ok: result.ok ?? true, item: summarizeJob(result.job || result) }, `Result ${submitId}`);
    }
    case "repl":
      return repl();
    default:
      throw new Error(`Unknown command: ${command}`);
  }
}

function splitCommand(line) {
  const args = [];
  let current = "";
  let quote = null;
  let escape = false;
  for (const char of line) {
    if (escape) {
      current += char;
      escape = false;
    } else if (char === "\\") {
      escape = true;
    } else if (quote) {
      if (char === quote) quote = null;
      else current += char;
    } else if (char === "'" || char === '"') {
      quote = char;
    } else if (/\s/.test(char)) {
      if (current) {
        args.push(current);
        current = "";
      }
    } else {
      current += char;
    }
  }
  if (quote) throw new Error(`Unclosed quote: ${quote}`);
  if (current) args.push(current);
  return args;
}

async function repl() {
  replMode = true;
  if (!jsonOutput) console.log("Lovart REPL. Type 'help' for commands, 'exit' to quit.");
  const rl = readline.createInterface({ input, output: outputStream, prompt: "lovart> " });
  while (true) {
    const raw = await rl.question("lovart> ");
    const line = raw.trim();
    if (!line) continue;
    if (["exit", "quit"].includes(line)) break;
    if (line === "help") {
      console.log('Examples: text2image --prompt "poster" | frames2video --prompt "cinematic" --first-frame a.png --last-frame b.png | asset_upload --asset-type image --source ./person.png | query_result --submit-id job_123');
      continue;
    }
    try {
      await main(splitCommand(line), false);
    } catch (error) {
      if (jsonOutput) console.log(JSON.stringify({ ok: false, error: { message: error.message, type: error.name } }));
      else console.error(`Error: ${error.message}`);
    }
  }
  rl.close();
}

async function main(argv = process.argv.slice(2), exitOnError = true) {
  const parsed = parseArgs(argv);
  jsonOutput = parsed.globals.json;
  rawOutput = parsed.globals.raw;
  if (parsed.command === "--help" || parsed.command === "-h") {
    console.log(rootHelp());
    return;
  }
  if (!parsed.command) return repl();
  if (parsed.options.help || parsed.rawArgs.includes("--help")) {
    if (!COMMANDS[parsed.command]) throw new Error(`Unknown command: ${parsed.command}`);
    console.log(commandHelp(parsed.command));
    return;
  }
  try {
    await runCommand(parsed.command, parsed.options);
  } catch (error) {
    if (jsonOutput) console.log(JSON.stringify({ ok: false, error: { message: error.message, type: error.name } }, null, 2));
    else console.error(`Error: ${error.message}`);
    if (exitOnError && !replMode) process.exit(1);
    if (!exitOnError) throw error;
  }
}

await main();
